TLM.f("Tempora/Quad6-6r:Prelude",{"rite":true,"source":"Divinum Officium","title":"Vazmeno bdijenje","items":[{"kind":"section","la":"Benedictio ignis","hr":"","rows":[{"la":"[Hora competenti tobaleis cooperiuntur altaria, sed candelæ exstinctæ manent usque ad principium Missæ. Interim excutitur ignis de lapide, et ex eo accenduntur carbones.]","hr":" "},{"la":"[Celebrans induitur amictu, alba, cingulo, stola et pluviali violacei coloris; ministri sacri amictu, alba, cingulo, diaconus stola et dalmatica, subdiaconus tunicella, eiusdem coloris.]","hr":" "},{"la":"[(Sacerdos induitur amictu, alba, cingulo, stola et pluviali violaceo, vel manet sine casula.)]","hr":" "},{"la":"[Adstantibus ministris, seu ministrantibus cum cruce, aqua benedicta et incenso, sive ante portam, sive in aditu ecclesiæ, vel intus eam, ubi scilicet populus ritum sacrum melius sequi possit, celebrans benedicit novum ignem, dicens:]\n℣. Dóminus vobíscum. ℟. Et cum spíritu tuo.\nOrémus.\nDeus, qui per Fílium tuum, angulárem scílicet lápidem, claritátis tuæ ignem fidélibus contulísti: prodúctum e sílice, nostris profutúrum úsibus, novum hunc ignem sanctí + fica: et concéde nobis, ita per hæc festa paschália cœléstibus desidériis inflammári; ut ad perpétuæ claritátis, puris méntibus, valeámus festa pertíngere. Per eúndem Christum Dóminum nostrum.\n℟. Amen.","hr":"Gospodin s vama. I s duhom tvojim.\nPomolimo se.\nBože, koji si po svojemu Sinu, ugaonom kamenu, podao svojim vjernicima oganj svoje sjajnosti, posveti ovaj novi oganj, izvabljen iz kremena, našim potrebama za korist, i podaj nam, da nas ovi vazmeni praznici tako snažno ražegu nebeskim željama, te čistim dušama zavrijedimo doprijeti k praznicima vječne sjajnosti. Po istom Gospodinu . . .","src":"Kniewald 1942, str. 268"},{"la":"[Deinde ignem ter aspergit, nihil dicens.]","hr":" "},{"la":"[Acolythus, seu unus ministrantium, assumens de carbonibus benedictis, ponit in thuribulo; celebrans vero ponit incensum in thuribulo, benedicens illud more solito, ignemque ter adolet incenso.]","hr":" "}]},{"kind":"section","la":"De benedictione cerei Paschalis","hr":"","rows":[{"la":"[Novo igne benedicto, acolythus, seu unus ministrantium, portat cereum paschalem in medium, ante celebrantem, qui cum stilo, inter extrema foramina ad insertionem granorum incensi destinata, incidit crucem. Deinde facit super eam litteram græcam Alpha, subtus vero litteram Omega, et inter bracchia crucis quatuor numeros exprimentes annum currentem, interim dicens:]\nChristus heri et hódie, (incidit hastam erectam)\nPrincípium et Finis, (incidit hastam transversam)\nAlpha (incidit supra hastam erectam litteram &Alpha;)\net Omega; (incidit subtus hastam erectam litteram &Omega;)\nIpsíus sunt témpora (incidit primum numerum anni currentis in angulo sinistro superiore crucis)\net sǽcula; (incidit secundum numerum anni currentis in angulo dextro superiore crucis)\nIpsi gloria et imperium (incidit tertium numerum anni currentis in angulo sinistro inferiore crucis)\nper universa æternitátis sǽcula. Amen. (incidit quartum numerum anni currentis in angulo dextro inferiore crucis)","hr":""},{"la":"[Incisione crucis et aliorum signorum, quæ coloribus vel alio modo antea præparari possunt, peracta, diaconus, seu alius ministrantium, præbet celebranti grana incensi, quæ idem celebrans, si non sunt benedicta ter aspergit et ter adolet incenso, nihil dicens. Deinde infigit quinque grana in foramina, interim dicens:]\nPer sua sancta vúlnera\ngloriósa\ncustódiat\net consérvet nos\nChristus Dóminus. Amen.","hr":""},{"la":"[Tum diaconus, seu unus ministrantium, porrigit celebranti parvam candelam, de novo igne accensam, qua cereum accendit, dicens:]\nLumen Christi glorióse resurgéntis\nDíssipet ténebras cordis et mentis.\n[Mox, celebrans benedicit cereum accensum, dicens:]\n℣. Dóminus vobíscum. ℟. Et cum spíritu tuo.\nOrémus.\nVéniat, quǽsumus, omnípotens Deus, super hoc incénsum céreum larga tuæ bene + dictiónis infúsio: et hunc noctúrnum splendórem invisíbilis regenerátor, inténde; ut non solum sacrifícium, quod hac nocte litátum est, arcána lúminis tui admixtióne refúlgeat; sed in quocúmque loco ex hujus sanctificatiónis mystério aliquid fúerit deportátum, expúlsa diabólicæ fraudis nequítia, virtus tuæ majestátis assístat. Per Christum Dóminum nostrum.\n℟. Amen.","hr":""},{"la":"[Interim luminaria ecclesiæ exstinguuntur.]","hr":" "}]},{"kind":"section","la":"De solemni processione","hr":"","rows":[{"la":"[Tum celebrans iterum ponit incensum in thuribulo; postea diaconus, depositis paramentis violaceis, et indutus stola et dalmatica albi coloris, accipit cereum paschalem accensum, et ordinatur processio: præcedit thuriferarius, sequitur subdiaconus cum cruce, diaconus cum cereo accenso, post eum statim celebrans, deinde clerus per ordinem, et populus.]","hr":" "},{"la":"[(Tum sacerdos, depositis paramentis violaceis, et indutus stola et dalmatica albi coloris, iterum ponit incensum in thuribulo; postea accipit cereum paschalem accensum, et ordinatur processio: precedit thuriferarius, sequitur crucifer, post eum statim sacerdos cum cereo accenso, deinde ceteri ministrantes, et populus.)]","hr":" "},{"la":"[Cum diaconus ingressus est ecclesiam, stans, cantat solus:]\n℣. Lumen Christi.\n[cui omnes alii, prater subdiaconum et thuriferarium, genuflectentes versus cereum benedictum, respondent:]\n℟. Deo grátias.\n[Celebrans vero de cereo benedicto propriam candelam accendit.]","hr":"Svijetlo Kristovo.\n\nBogu hvala!","src":"Kniewald 1942, str. 269"},{"la":"[Procedens ad medium ecclesiæ, ibi eodem modo diaconus altius cantat]\n℣. Lumen Christi.\n[cui omnes, ut supra, genuflectentes, respondent:]\n℟. Deo grátias.\n[Et de cereo benedicto accenduntur candelæ cleri.]","hr":"Svijetlo Kristovo.\n\nBogu hvala!","src":"Kniewald 1942, str. 269"},{"la":"[Tertio procedens ante altare, in medio chori, rursum adhuc altius cantat:]\n℣. Lumen Christi.\n[cui tertio omnes, ut supra, genuflectentes, respondent:]\n℟. Deo grátias.\n[Et accenduntur candelæ: populi de cereo benedicto, et luminaria ecclesiæ.]","hr":"Svijetlo Kristovo.\n\nBogu hvala!","src":"Kniewald 1942, str. 269"},{"la":"[(Cum sacerdos ingressus est ecclesiam, stans, cantat solus: Lumen Christi, cui omnes alii, prater cruciferum et thuriferarium, genuflectentes versus cereum benedictum, respondent: Deo grátias. Tunc unus ex ministrantibus de cereo benedicto candelam pro sacerdote accendit.]\n[Procedens ad medium ecclesiæ, ibi eodem modo sacerdos altius cantat: Lumen Christi, cui omnes, ut supra, genuflectentes, respondent: Deo grátias. Et de cereo benedicto accenduntur candelæ ministrantium.]\n[Tertio procedens ante altare, in medio chori, rursum adhuc altius cantat: Lumen Christi, cui tertio omnes, ut supra genuflectentes, respondent: Deo grátias. Et accenduntur candelæ populi de cereo benedicto, et luminaria ecclesiæ.)]","hr":" "}]},{"kind":"section","la":"De præconio paschali","hr":"","rows":[{"la":"[Tunc celebrans vadit ad locum suum in choro, in latere Epistolæ; subdiaconus cum cruce stat in latere Evangelii, contra legile; clerus locum suum occupat in scamnis.]\n[Diaconus deponit cereum paschalem in medio chori, supra parvum sustentaculum, et, postquam celebrans posuerit incensum in thuribulo, accipiens librum, petit benedictionem, dicens:]\nIube, domne, benedícere.\n[Et celebrans subiungit:]\nDóminus sit in corde tuo, et in lábiis tuis, ut digne et competénter annúntiem suum paschále præcónium: in nómine Patris, et Fílii, + et Spíritus Sancti.\n[Et diaconus respondet:]\nAmen.\n[(Sacerdos deponit cereum paschalem in medio chori, supra parvum sustentaculum, seque recipit ad abacum; crucifer stat in latere Evangelii, contra legile; ceteri ministrantes disponuntur hinc et inde.]\n[Sacerdos vero, postquam posuerit incensum in thuribulo, accepto libro, dicit: Iube, Dómine, benedícere. - Dóminus sit in corde meo, et in lábiis meis: ut digne et competénter annúntiem suum paschále præcónium. Amen.)]","hr":""},{"la":"[Postea diaconus vadit ad legile, strato albo coopertum, et ponit super eo librum, et incensat; deinde, circumiens cereum paschalem, etiam illum thurificat.]\n[Tunc surgentibus omnibus, et stantibus, ut fit ad Evangelium, diaconus cantat præconium paschale, habens ante se cereum paschalem, a dextris altare, a sinistris aulam ecclesiæ. Dum canitur præconium paschale, convenit, ut clerus et populus candelas accensas gestent.]","hr":" "},{"la":"[(Postea sacerdos vadit ad legile, strato albo coopertum, et ponit super eo librum, et incensat; deinde, circumiens cereum paschalem, etiam illum thurificat.]\n[Tunc surgentibus omnibus, et stantibus, ut fit ad Evangelium, ipse sacerdos cantat vel legit præconium paschale, habens ante se cereum paschalem, a dextris altare, a sinistris aulam ecclesiæ. Dum canitur præconium paschale, convenit, ut clerus et populus candelas accensas gestent.)]","hr":" "},{"la":"Exsúltet iam Angélica turba coelórum: exsúltent divína mystéria: et pro tanti Regis victória tuba ínsonet salutáris. Gáudeat et tellus tantis irradiáta fulgóribus: et ætérni Regis splendóre illustráta, totíus orbis se séntiat amisísse calíginem. Lætétur et mater Ecclésia, tanti lúminis adornáta fulgóribus: et magnis populórum vócibus hæc aula resúltet. Quaprópter astántes vos, fratres caríssimi, ad tam miram huius sancti lúminis claritátem, una mecum, quæso, Dei omnipoténtis misericórdiam invocáte. Ut, qui me non meis méritis intra Levitárum númerum dignatus est aggregáre: lúminis sui claritátem infúndens, Cérei huius laudem implére perfíciat. Per Dominum nostrum Jesum Christum, Fílium suum: qui cum eo vivit et regnat in unitáte Spíritus Sancti Deus: Per omnia sǽcula sæculórum.\n℟. Amen.\n℣. Dóminus vobíscum.\n℟. Et cum Spíritu tuo.\n℣. Sursum corda.\n℟. Habémus ad Dóminum.\n℣. Grátias agámus Dómino Deo nostro.\n℟. Dignum et iustum est.\nVere dignum et iustum est, invísibilem Deum Patrem omnipoténtem Filiúmque eius unigénitum, Dominum nostrum Iesum Christum, toto cordis ac mentis afféctu et vocis ministério personáre. Qui pro nobis ætérno Patri Adæ débitum solvit: et véteris piáculi cautiónem pio cruóre detérsit. Hæc sunt enim festa paschália, in quibus verus ille Agnus occíditur, cuius sánguine postes fidelium consecrántur. Hæc nox est, in qua primum patres nostros, fílios Israël edúctos de Ægýpto, Mare Rubrum sicco vestígio transíre fecísti. Hæc ígitur nox est, quæ peccatórum ténebras colúmnæ illuminatióne purgávit. Hæc nox est, quæ hódie per univérsum mundum in Christo credéntes, a vítiis sǽculi et calígine peccatórum segregátos, reddit grátiæ, sóciat sanctitáti. Hæc nox est, in qua, destrúctis vínculis mortis, Christus ab ínferis victor ascéndit. Nihil enim nobis nasci prófuit, nisi rédimi profuísset. O mira circa nos tuæ pietátis dignátio! O inæstimábilis diléctio caritátis: ut servum redimeres, Fílium tradidísti! O certe necessárium Adæ peccátum, quod Christi morte delétum est! O felix culpa, quæ talem ac tantum méruit habére Redemptórem! O vere beáta nox, quæ sola méruit scire tempus et horam, in qua Christus ab ínferis resurréxit! Hæc nox est, de qua scriptum est: Et nox sicut dies illuminábitur: Et nox illuminátio mea in deliciis meis. Huius ígitur sanctificátio noctis fugat scélera, culpas lavat: et reddit innocéntiam lapsis et mæstis lætítiam. Fugat ódia, concórdiam parat et curvat impéria.","hr":"Neka već klikne množina anđela u nebesima, neka uskliknu božanstvene tajne, i za tolikoga Kralja pobjedu, neka jekne trublja spasenja! Neka se raduje i zemlja, tolikim obasjana blijescima i osvijetljena sjajem vječnoga Kralja, neka oćuti, da je po svem svijetu nestalo mraka. Neka se raduje i mati Crkva, tolikoga svijetla ukrašena blijescima i ova dvorana neka poigra od silnih glasova naroda. Zato molim nazočne vas, preljubazna braćo, kod tako divne jasnosti ovoga svetoga svijetla, prizovite zajedno sa mnom smilovanje svemogućega Boga, koji je mene, ne radi mojih zasluga, pridružio broju levita, da ispuni i savrši pohvalu ove svijeće, ulijevajući u dušu moju jasnost svojega svijetla, po Gospodinu našem Isusu Kristu, Sinu svojemu, koji s njime živi i kraljuje u jedinstvu Duha Svetoga, Bog, u sve vijeke vjekova.\nAmen.\nGospodin s Vama.\nI s duhom Tvojim.\nGore srca.\nImamo kod Gospodina.\nHvale uzdajmo Gospodinu Bogu našemu.\nDostojno je i pravedno.\nU istinu je dostojno i pravedno, pravo i spasonosno, nevidljivoga Boga, Oca svemogućega, i Sina njegova jedinorođenoga, Isusa Krista, svom usrdnošću srca glasno slaviti, jer je on za nas vječnomu Ocu platio Adamov dug i zadužnicu iz stare krivnje milostivom krvlju izbrisao. Jer ovo su blagdani vazmeni, u kojima se onaj istiniti Jaganjac kolje, čijom se krvlju posvećuju dovratnici vjernika. Ovo je noć, u kojoj si najprije oce naše, sinove Izraelove, izveo iz Egipta i suhom ih stopom preveo preko Crvenoga mora. Ovo je dakle noć, koja tamu grijeha očisti rasvjetom stupa ognjenoga. Ovo je noć, koja danas po svemu kolikome svijetu one, koji u Krista vjeruju, odlučene od opačina ovoga vijeka i od magle grijeha, povraća milosti, pridružuje svetosti, skršivši okove smrti. Ovo je noć, u kojoj se Krist pobjednik iz podzemlja uzdiže. Jer ništa nam ne bi koristilo rođenje, da nijesmo zadobili otkupljenje. O divna li udostojavanja milostivosti Tvoje k nama! O neprocjenjiva li milovanja ljubavi: da sužnja otkupiš, Sina si predao! O zacijelo potrebita grijeha Adamova, koji se izbrisa smrću Kristovom! O sretne krivnje, koja zavrijedi takova i tolikog Otkupitelja! O doista blažene noći, koja sama zavrijedi, znati vrijeme i čas, kad Krist iz mrtvih uskrsne! Ovo je noć, za koju je pisano: I noć će se prosvijetliti kao dan i noć je rasvjeta moja u raskošima mojim. Posvećenje dakle ove noći odgoni zlodjela, pere krivice i povraća nedužnost palima, a žalosnima radost; odgoni nenavisti, pripravlja slogu i prigiba vlasti.","src":"Kniewald 1942, str. 270-271"},{"la":"In huius ígitur noctis grátia, súscipe, sancte Pater, incénsi huius sacrifícium vespertínum: quod tibi in hac Cérei oblatióne solémni, per ministrórum manus de opéribus apum, sacrosáncta reddit Ecclésia. Sed iam colúmnæ huius præcónia nóvimus, quam in honórem Dei rútilans ignis accéndit. Qui licet sit divísus in partes, mutuáti tamen lúminis detriménta non novit. Alitur enim liquántibus ceris, quas in substántiam pretiósæ huius lámpadis apis mater edúxit. O vere beáta nox, quæ exspoliávit Ægýptios, ditávit Hebrǽos! Nox, in qua terrénis cæléstia, humánis divína iungúntur.","hr":"U blagodati dakle ove noći primi, sveti Oče, večernju žrtvu ovoga tamjana, koju Ti presveta Crkva dariva ovim svečanim prikazivanjem svijeće, kroz ruke službenika, a od pčelinjih djela. Ta mi već znamo hvalospjev ovoga stupa, što ga na čast Božju žarki oganj užiže; koji, ako i jest razdijeljen na česti, ipak ne pozna, da mu je na štetu, što uzajmi svjetlost, jer se hrani s rastopljenim voskom, što ga za građu dragocjene ove svijeće izvede pčela. O zaista blažena noći, koja oplijeni Egipćane, a obogati Židove! Noć, u kojoj se spajaju zemaljska sa nebeskim, božanska sa čovječanskim.","src":"Kniewald 1942, str. 272"},{"la":"Orámus ergo te, Dómine: ut Céreus iste in honórem tui nóminis consecrátus, ad noctis huius calíginem destruéndam, indefíciens persevéret. Et in odórem suavitátis accéptus, supérnis lumináribus misceátur. Flammas eius lúcifer matutínus invéniat. Ille, inquam, lúcifer, qui nescit occásum. Ille, qui regréssus ab ínferis, humáno géneri serénus illúxit. Precámur ergo te, Dómine: ut nos fámulos tuos, omnémque clerum, et devotíssimum pópulum: una cum beatíssimo Papa nostro Leóne, et Antístite nostro N., quiéte témporum concéssa, in his paschálibus gáudiis, assídua protectióne régere, gubernáre et conserváre digneris.","hr":"Molimo Te dakle, Gospodine, da ova svijeća, posvećena časti Tvojega imena, ustraje neoslabljena, na zator pomrčine ove noći. I primljena kao blagoduhi miris neka se primiješa višnjim svijećnjacima. Plamene njezine neka nađe jutarnji lučonoša. Onaj, velim, lučonoša, koji ne zna zapada. On, što vedar zasja rodu ljudskomu, vrativši se iz mrtvih. Molimo Te, dakle, Gospodine, da se dostojiš sveudiljnom zaštitom vladati, upravljati i sačuvati nas, sluge svoje i sve svećenstvo, i prebogoljubni puk, skupa s preblaženim papom našim Lavom i biskupom I. Daj nam, Gospodine, mirna vremena u ovim vazmenim radostima.","src":"Kniewald 1942, str. 272"},{"la":"Réspice étiam ad eos, qui nos in potestáte regunt, et, ineffábili pietátis et misericórdiæ tuæ múnere, dírige cogitatiónes eórum ad iustítiam et pacem, ut de terréna operositáte ad cæléstem pátriam pervéniant cum omni populo tuo.","hr":"","key":"vigil:exsultet-respice"},{"la":"Per eúndem Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus: per ómnia sǽcula sæculórum.\n℟. Amen.","hr":"Po istom Gospodinu našem Isusu Kristu, Sinu Tvomu, koji s Tobom živi i kraljuje u jedinstvu Duha Svetoga, Bog, u sve vijeke vjekova\nAmen.","src":"Kniewald 1942, str. 272"}]},{"kind":"section","la":"De lectionibus","hr":"","rows":[{"la":"[Post præconium paschale, diaconus, depositis paramentis albis, assumit violacea, et vadit ad celebrantem.]","hr":" "},{"la":"[(Post præconium paschale, sacerdos deponit dalmaticam et stolam albi coloris, et, indutus iterum stola et pluviali violaceis, redit ad legile.)]","hr":" "},{"la":"[Postea leguntur lectiones, sine titulo, nec in earum fine respondetur Deo gratias. Leguntur vero a lectore, in medio chori, ante cereum benedictum, ita quidem ut lector habeat a dextris altare, a sinistris aulam ecclesiæ. Celebrans et ministri, clerus et populus, sedentes auscultant.]","hr":" "},{"la":"[(Postea leguntur lectiones, sine titulo, nec in earum fine respondetur Deo gratias. Leguntur vero a sacerdote, in medio chori, ante cereum benedictum, ita quidem ut sacerdos habeat a dextris altare, a sinistris aulam ecclesiæ. Ministrantes et populus sedentes auscultant.]\n[Si vero adsit clericus lector, omnia peraguntur, ut supra.)]","hr":" "},{"la":"[In fine lectionis, vel post canticum, dicuntur orationes hoc modo: omnes surgunt; celebrans dicit Orémus, diaconus Flectámus genua, et omnes, una cum ipso celebrante, flexis genibus, per aliquod temporis spatium in silentio orant; dicto a diacono Leváte, omnes surgunt, et celebrans dicit orationem, in tono feriali, et iunctis manibus.]","hr":" "},{"la":"[(In fine lectionis, vel post canticum, dicuntur orationes hoc modo: omnes surgunt; sacerdos, stans ante legile, dicit: Orémus. Flectámus genua, et omnes, una cum ipso sacerdote, flexis genibus, per aliquod temporis spatium in silentio orant; dicto a sacerdote Leváte, omnes surgunt, et ipse dicit orationem, in tono feriali, et iunctis manibus.)]","hr":" "},{"la":"[Leguntur vero quatuor sequentes lectiones, cum suis canticis, et orationibus.]","hr":" "},{"la":"[Lectio prima]\nGen. 1:1-31; 2:1-2\nIn princípio creávit Deus cælum et terram. Terra áutem erat inánis et vácua, et ténebræ erant super fáciem abýssi: et Spíritus Dei ferebátur super aquas. Dixítque Deus: Fiat lux. Et facta est lux. Et vidit Deus lucem quod esset bona: et divísit lucem a ténebris. Appellavítque lucem Diem, et ténebras Noctem: factúmque est véspere et mane, dies unus. Dixit quoque Deus: Fiat firmaméntum in médio aquárum: et dívidat aquas ab aquis. Et fecit Deus firmaméntum, divisítque aquas quæ erant sub firmaménto, ab his quæ erant super firmaméntum. Et factum est ita. Vocávit Deus firmaméntum Cælum: et factum est véspere et mane, dies secúndus. Dixit vero Deus: Congregéntur aquæ, quæ sub cælo sunt, in locum unum: et appáreat árida. Et factum est ita. Et vocávit Deus aridam, Terram, congregationísque aquárum appellávit Mária. Et vidit Deus quod esset bonum. Et ait: Gérminet terra herbam viréntem, et faciéntem semen, et lignum pomíferum fáciens fructum iuxta genus suum, cuius semen in semetípso sit super terram. Et factum est ita. Et prótulit terra herbam viréntem, et faciéntem semen iuxta genus suum, lignúmque fáciens fructum, et habens unumquódque seméntem secúndum spéciem suam. Et vidit Deus quod esset bonum. Et factum est véspere et mane, dies tértius. Dixit áutem Deus: Fiant luminária in firmaménto cæli, et dívidant diem ac noctem, et sint in signa et témpora, et dies et annos: ut lúminent terram. Et factum est ita. Fecítque Deus duo luminária magna: luminária maius, ut præésset diéi, et lumináre minus, ut præésset nocti: et stellas. Et pósuit eas in firmaménto cæli, ut lucérent super terram, et præéssent diéi ac nocti, et divíderent lucem ac ténebras. Et vidit Deus quod esset bonum. Et factum est véspere et mane, dies quartus. Dixit étiam Deus: Prodúcant aquæ réptile ánimæ vivéntis, et volátile super terram sub firmaménto cæli. Creavítque Deus cete grándia, et omnem ánimam vivéntem atque motábilem, quam prodúxerant aquæ in spécies suas, et omne volátile secúndum genus suum. Et vidit Deus quod esset bonum. Benedixítque eis, dicens: Créscite, et multiplicámini, et repléte aquas maris: avésque multiplicéntur super terram. Et factum est véspere et mane, dies quintus. Dixit quoque Deus: Prodúcat terra ánimam vivéntem in génere suo: iuménta, et reptília, et béstias terræ secúndum spécies suas. Factúmque est ita. Et fecit Deus béstias terræ juxta spécies suas, et juménta, et omne réptile terræ in génere suo. Et vidit Deus quod esset bonum, et ait: Faciámus hóminem ad imáginem et similitúdinem nostram: et præsit píscibus maris, et volatílibus cæli, et béstiis, universáeque terræ, omníque réptili quod movétur in terra. Et creávit Deus hóminem ad imáginem suam: ad imáginem Dei creávit illum, másculum et féminam creávit eos. Benedixítque illis Deus, et ait: Créscite et multiplicámini, et repléte terram, et subjícite eam, et dominámini píscibus maris, et volatílibus cæli, et univérsis animántibus, quæ movéntur super terram. Dixítque Deus: Ecce dedi vobis omnem herbam afferéntem semen super terram, et univérsa ligna quæ habent in semetípsis seméntem géneris sui, ut sint vobis in escam: et cunctis animántibus terræ, omníque vólucri cæli, et univérsis, quæ movéntur in terra, et in quibus est ánima vivens, ut hábeant ad vescéndum. Et factum est ita. Vidítque Deus cuncta quæ fécerat: et erant valde bona. Et factum est véspere et mane, dies sextus. Igitur perfécti sunt cæli et terra, et omnis ornátus eórum. Complevítque Deus die séptimo opus suum quod fécerat: et requiévit die séptimo ab univérso ópere quod patrárat.\nOrémus.\n℣. Flectámus génua.\n℟. Leváte.\nDeus, qui mirabíliter creásti hóminem, et mirabílius redemísti: da nobis, quǽsumus, contra oblectaménta peccáti, mentis ratióne persístere; ut mereámur ad ætérna gáudia perveníre.","hr":"I. Mojs. 1, 1-31 i 2, 1-2\nU početku Bog stvori nebo i zemlju. Zemlja je bila pusta i prazna, i tama je pokrivala bezdan, a Božji se dah nosio nad vodom. Tada reče Bog: Neka bude svjetlost! I bi svjetlost. I vidje Bog, da je svjetlost dobra i rastavi svjetlost od tame. I svjetlost prozva dan, a tamu noć, i bi večer i jutro, prvi dan. Opet reče Bog: Neka sred vode bude svod, koji neka dijeli vodu od vode. I učini Bog svod i rastavi vodu, koja je bila pod svodom od one, koja je bila nad svodom. I bi tako. I svod prozva Bog nebo, i bi večer i jutro, drugi dan. Zatim reče Bog: Neka se voda, što je pod nebom, skupi na jedno mjesto, da se pokaže suho. I bi tako. I suho prozva Bog zemlja, a skup vode more. I vidje Bog, da je dobro. I reče: Neka iz zemlje nikne zelena trava, koja daje sjeme, i plodna stabla, koja prema svojoj vrsti daju plod, koji neka ima svoje sjeme u sebi, da se plodi po zemlji. I bi tako. I pokri zemlju zelena trava, koja prema svojoj vrsti daje sjeme, i plodna stabla, koja prema svojoj vrsti imaju u sebi sjeme. I vidje Bog, da je dobro. I bi večer i jutro, treći dan. Nato reče Bog: Neka na nebeskom svodu budu svjetlila, da dijele dan od noći i da budu znacima vremena, dana i godina, da svijetle na nebeskom svodu i rasvjetljuju zemlju. I bi tako. A Bog učini dva velika svjetlila: veće svjetlilo, da upravlja dan, a manje svjetlo, da upravlja noć, i zvijezde. I postavi ih na nebeskom svodu, da svijetle na zemlju i upravljaju dan i noć i dijele svijetlo od tame. I vidje Bog, da je dobro. I bi večer i jutro, četvrti dan. Još reče Bog: Neka voda dade životinje, koje se giblju po vodi, i ptice, koje lete nad zemljom pod nebeskim svodom. Još stvori Bog velike ribe i svako živo biće, koje se giblje, koje je dala voda po njihovim vrstama, i sve ptice po svojoj vrsti. I vidje Bog, da je dobro i blagoslovi ih govoreći: Rastite i množite se i napunite more, a ptice neka se množe na zemlji. I bi večer i jutro, peti dan. I reče Bog: Neka zemlja dade živa bića po njihovu rodu: stoku i gmizavce i zemaljske zvijeri po njihovim vrstama. I bi tako. I učini Bog zemaljske zvijeri po njihovim vrstama, i stoku i sve gmizavce po njihovu rodu. Kad vidje Bog, da je dobro, reče: Učinimo čovjeka na svoju sliku i priliku, da bude nad morskim ribama i nebeskim pticama i zvijerima, svom zemljom i svim zemaljskim gmizavcima. I Bog stvori čovjeka na svoju sliku, stvori ga na Božju sliku, stvori ih muško i žensko. I blagoslovi ih Bog i reče: Rastite i množite se i napunite zemlju i pokorite ju i vladajte nad morskim ribama, nebeskim pticama i svim životinjama, koje se giblju po zemlji. Još reče Bog: Sve bilje, koje na zemlji daje sjeme, sva stabla, koja u sebi imaju sjeme prema svomu rodu, dao sam, da vama bude za hranu, kao i svim zemaljskim životinjama i svim nebeskim pticama i svemu, što se po zemlji giblje i što živi, da imadu za hranu. I bi tako. I vidje Bog, što je učinio i bilo je vrlo dobro. I bi večer i jutro, šesti dan. Tako je dovršeno nebo i zemlja i sav njihov uređaj. I sedmoga dana dovrši Bog svoje djelo, koje je učinio, i od svoga djela, koje je učinio, počinu sedmi dan.\nPomolimo se!\nPrignite i t. d.\n\nBože, koji si divno stvorio čovjeka, a divnije otkupio, daj nam, molimo, da nasladama grijeha odolijevamo razborom duše, te zavrijedimo doći vječnim radostima.","src":"Kniewald 1942, str. 273-275"},{"la":"[Lectio secunda]\nExod 14:24-31; 15:1\nIn diébus illis: Factum est in vigília matutína, et ecce respíciens Dóminus super castra Ægyptiórum per colúmnam ignis et nubis, interfécit exércitum eórum: et subvértit rotas cúrruum, ferebantúrque in profúndum. Dixérunt ergo Ægýptii: Fugiámus Israëlem: Dóminus enim pugnat pro eis contra nos. Et ait Dóminus ad Móysen: Exténde manum tuam super mare, ut revertántur aquæ ad Ægýptios super currus et équites eórum. Cumque extendísset Móyses manum contra mare, revérsum est primo dilúculo ad priórem locum: fugientibúsque Ægýptiis occurrérunt aquæ, et invólvit eos Dóminus in médiis flúctibus. Reversáeque sunt aquæ, et operuérunt currus et équites cuncti exércitus Pharaónis, qui sequéntes ingréssi fúerant mare: nec unus quidem supérfuit ex eis. Fílii áutem Israël perrexérunt per médium sicci maris, et aquæ eis erant quasi pro muro a dextris et a sinístris: liberavítque Dóminus in die illa Israël de manu Ægyptiórum. Et vidérunt Ægýptios mórtuos super littus maris, et manum magnam. quam exercúerat Dóminus contra eos: timuítque pópulus Dóminum, et credidérunt Dómino, et Móysi servo eius. Tunc cécinit Móyses, et fílii Israël carmen hoc Dómino, et dixérunt:\n[Canticum]\nExod 15:1-2\nCantémus Dómino: glorióse enim honorificátus est: equum et ascensórum proiécit in mare: adiútor, et protéctor factus est mihi in salútem.\n℣. Hic Deus meus, et honorificábo eum: Deus patris mei, et exaltábo eum.\n℣. Dóminus cónterens bella: Dóminus nomen est illi.\nOrémus.\n℣. Flectámus génua.\n℟. Leváte.\nDeus, cuius antíqua mirácula étiam nostris sǽculis coruscáre sentímus: dum quod uni pópulo, a persecutióne Ægyptíaca liberándo, déxteræ tuæ poténtia contulísti, id in salútem géntium per aquam regeneratiónis operáris: præsta; ut in Abrahæ fílios, et in Israelíticam dignitátem, totíus mundi tránseat plenitúdo.","hr":"II. Mojs. 14, 23-31, 15, 1\nPred zoru onoga dana Gospodin pogleda egipatski tabor iz stupa od ognja i oblaka, porazi njihovu vojsku i prevrne točkove i kola, da su pali u dubinu mora. Tada reknu Egipćani: Bježimo od Izraela, jer se protiv nas Gospodin bori za njih. I Gospodin reče Mojsiju: Pruži svoju ruku prema moru, da se voda vrati k Egipćanima, na kola i na njihove konjanike. Kad Mojsije pruži ruku prema moru, more se u zoru vrati na svoje mjesto, a Egipćane, koji su bježali, zahvati voda i Gospodin ih pokri valovima. I voda se vrati i pokri kola i konjanike sve Faraonove vojske, koji su goneći Izraelce zašli u more: nijedan od njih nije ostao. A Izraelovi sinovi pređu sred mora po suhu, a voda im je bila kao zid s desna i s lijeva. I onoga dana oslobodi Gospodin Izraela od egipatske ruke. A Izraelci su vidjeli mrtve Egipćane na morskoj obali i jaku ruku, koju je Gospodin podigao na njih. I narod se bojao Gospodina i vjerovao je Gospodinu i njegovu sluzi Mojsiju. Tada zapjeva Mojsije i Izraelovi sinovi Gospodinu ovu pjesmu:\n\nII. Mojs. 15, 1-2\nPjevajmo Gospodinu, jer se slavno uzveličao, konja i konjanika baci u more. On je moj pomoćnik i zaštitnik, on je moj spasitelj.\nOvo je moj Bog, slavit ću ga, Bog mojega oca, uzvisivat ću ga.\nGospodin, koji satire ratove, Gospodin je njegovo ime.\nPomolimo se.\nPrignimo . . .\n\nTvoja drevna čudesa, Gospodine sveti, Bože, još i u našim vjekovima osjećamo gdje se blistaju: jer što snagom desnice svoje dade jednomu puku izbavivši ga od progonstva, to djeluješ za spasenje narodâ vodom preporođenja; zato podaj, da svega svijeta punina dostigne dostojanstvo sinova Abrahamovih i izabranog naroda.","src":"Kniewald 1942, str. 280-281"},{"la":"[Lectio tertia]\nIsa 4:2-6\nIn die illa erit germen Dómini in magnificéntia, et glória, et fructus terræ sublímis, et exultátio his, qui salváti fúerint de Israël. Et erit: Omnis qui relíctus fúerit in Sion, et resíduus in Ierúsalem, sanctus vocábitur, omnis qui scriptus est in vita in Ierúsalem. Si ablúerit Dóminus sordes filiárum Sion, et sánguinem Ierúsalem láverit de médio eius, in spíritu iudícii, et spíritu ardóris. Et creábit Dóminus super omnem locum montis Sion, et ubi invocátus est, nubem per diem, et fumum, et splendórem ignis flammántis in nocte: super omnem enim glóriam protéctio. Et tabernáculum erit in umbráculum diéi ab æstu, et in securitátem, et absconsiónem a túrbine, et a plúvia.\n[Canticum]\nIsa 5:1-2\nVínea facta est dilécto in cornu, in loco úberi.\n℣. Et macériam circúmdedit, et circumfodit: et plantávit víneam Sorec: et ædificávit turrim in médio eius.\n℣. Et tórcular fodit in ea: vínea enim Dómini Sábaoth, domus Israël est.\nOrémus.\n℣. Flectámus génua.\n℟. Leváte.\nDeus, qui in ómnibus Ecclésiæ tuæ fíliis sanctórum prophetárum voce manifestásti, in omni loco dominatiónis tuæ, satórem te bonórum séminum, et electórum pálmitum esse cultórem: tríbue pópulis tuis, qui et vineárum apud te nómine censéntur, et ségetum; ut, spinárum et tribulórum squalóre resecáto, digna efficiántur fruge fecúndi.","hr":"U onaj će dan Gospodnja klica biti u veličanstvu i slavi, i plod će zemlje biti uzvišen na veselje onima iz Izraela, koji budu spaseni. A svaki, koji ostane u Sionu i u Jeruzalemu bit će svet, svaki koji bude upisan u broj živih u Jeruzalemu. Tada će Gospodin u duhu pravde i u duhu revnosti oprati nečistoću sionskih kćeri i oprat će Jeruzalem od krvi, koja je u njemu. I Gospodin će po svoj sinajskoj gori i na svakom mjestu, gdje bude čašćen, danju postaviti oblak, a noću dim i sjaj plamenoga ognja; jer će biti zaštićeno sve, što je slavno. A šator će biti, da po danu štiti od žege i bude utočište i sklonište od oluje i kiše.\n\nIz. 5, 1-2\nMoj ljubljeni ima vinograd na gori, na plodnomu mjestu.\nI ogradi ga i okopa, i nasadi vinograd Sorek i u njemu sagradi kulu.\nI u njemu iskopa tijesak, jer dom Izraelov je vinograd Gospodina Sabaot.\nPomolimo se.\nPrignimo i t. d.\n\nBože, koji si svima sinovima Crkve Tvoje očitovao glasom svetih proroka, da si na svakom mjestu kraljevstva svoga sijač dobroga sjemena i uzgojitelj izabranih čokota; daj narodima svojim, koji se kod Tebe nazivaju imenom vinograda i usjeva, pošto istrijebiše nečistoću trnja i korova, da postanu plodni dostojnim rodom,","src":"Kniewald 1942, str. 285-286"},{"la":"[Lectio quarta]\nDeut 31:22-30\nIn diébus illis: Scripsit ergo Móyses cánticum et dócuit fílios Israël. Præcepítque Dóminus Iósue fílio Nun et ait: Confortáre, et esto robústus: tu enim introdúces fílios Israël in terram, quam pollícitus sum, et ego ero tecum. Postquam ergo scripsit Moses verba legis huius in volúmine, atque conplévit: præcépit Levítis, qui portábant arcam fœ́deris Dómini dicens: Tóllite librum istum, et pónite eum in látere arcæ fœ́deris Dómini Dei vestri: ut sit ibi contra te in testimónium. Ego enim scio contentiónem tuam, et cervícem tuam duríssimam. Adhuc vivénte me, et ingrediénte vobíscum, semper contentióse egístis contra Dóminum: quanto magis cum mórtuus fúero? Congregáte ad me omnes maióres natu per tribus vestras, atque doctóres, et loquar audiéntibus eis sermónes istos, et invocábo contra eos cælum et terram. Novi enim quod post mortem meam iníque agétis, et declinábitis cito de via, quam præcépi vobis: et occúrrent vobis mala in extrémo témpore, quando fecéritis malum in conspéctu Dómini, ut irritétis eum per ópera mánuum vestrárum. Locútus est ergo Móyses, audiénte univérso cœtu Israël, verba cárminis huius, et ad finem usque conplévit:\n[Canticum]\nDeut. 32:1-4\nAtténde, cælum, et loquar: et áudiat terra verba ex ore meo.\n℣. Exspectétur sicut plúvia elóquium meum: et descéndant sicut ros verba mea, sicut imber super grámina.\n℣. Et sicut nix super fænum: quia nomen Dómini invocábo.\n℣. Date magnitúdinem Deo nostro: Deus, vera ópera eius, et omnes viæ eius iudícia.\n℣. Deus fidélis, in quo non est iníquitas: iustus et sanctus Dóminus.\nOrémus.\n℣. Flectámus génua.\n℟. Leváte.\nDeus, celsitúdo humílium et fortitúdo rectórum, qui per sanctum Móysen púerum tuum, ita erudíre pópulum tuum sacri cárminis tui decantatióne voluísti, ut illa legis iterátio fíeret étiam nostra diréctio: excíta in omnem iustificatárum géntium plenitúdinem poténtiam tuam, et da lætítiam, mitigándo terrórem; ut, ómnium peccátis tua remissióne delétis, quod denuntiátum est in ultiónem, tránseat in salútem.","hr":"5 Mojs. 31, 22-30\nU onaj dan Mojsije napisa pjesmu i nauči Izraelove sinove. I Gospodin zapovjedi Nunovu sinu Jozui i reče: Budi jak i hrabar, jer ćeš ti uvesti Izraelove sinove u zemlju koju sam obećao; ja ću biti s tobom. A kad je Mojsije svršio pisati naredbe ovoga zakona u knjizi, levitima, koji su nosili kovčeg Gospodnjega zavjeta, zapovjedi: Uzmite ovu knjigu i stavite je uz kovčeg zavjeta Gospodina Boga vašega, da bude ondje protiv tebe za svjedočanstvo. Jer ja poznam tvoj prkos i tvoju veliku tvrdoglavost. Kroz sve vrijeme, dok sam ja živio i radio među vama, radili ste uvijek prkosno protiv Gospodina. Koliko više, kad ja umrem? Skupite pred mene od svojih plemena sve starješine i učitelje, da im kažem, neka čuju ove riječi i da protiv njih sazovem na svjedočanstvo nebo i zemlju. Jer znam, da ćete poslije moje smrti raditi zlo i da ćete brzo napustiti put, koji sam vam propisao. Zato će vas na koncu stići nevolje, kad budete činili zlo pred Gospodinom, da ga srdite djelima svojih ruku. Sav je izraelski narod slušao, a Mojsije je govorio riječi ove pjesme i izgovorio ih je do kraja.\n\nV. Mojs. 32, 1-4\nČuj, nebo, što ću govoriti i zemlja neka čuje riječi mojih usta.\nNeka se očekuje moj govor kao kiša i neka padnu moje riječi kao rosa; kao pljusak na travu\ni kao snijeg na sijeno, jer ću zazvati ime Gospodnje.\nVeličajte našega Boga, jer su istinita njegova djela i pravedni svi njegovi putovi,\nBog je vjeran, u njemu nema nepravde, Gospodin je pravedan i svet.\nPomolimo se.\nPrignite i t. d.\n\nBože, uzvišenje poniznih i jakosti pravih, Ti si preko svetoga Mojsija, sluge svojega, tako htio poučiti svoj narod pjevanjem svete pjesme, da ono ponavljanje zakona bude i nama za upravljanje; probudi moć svoju u svoj punini opravdanih naroda, i daj radost ublaživši strah, da svojim otpuštenjem očistiš sve grijehe i što je kazano za odmazdu, neka se obrati na spasenje.","src":"Kniewald 1942, str. 287-288"}]},{"kind":"section","la":"De prima parte Litaniarum","hr":"","rows":[{"la":"[His expletis, a duobus cantoribus, in medio chori genuflexis, cantantur Litaniæ Sanctorum (quin tamen duplicentur) usque ad invocationem Propitius esto, omnibus genuflexis et respondentibus.]","hr":" "},{"la":"[(His expletis, a duobus cantoribus, seu, his deficientibus, ab ipso sacerdote, genuflexo in infimo gradu altaris, a latere Epistolæ, cantantur Litaniæ Sanctorum (quin tamen duplicentur) usque ad invocationem Propitius esto, omnibus genuflexis et respondentibus.)]\n℣. Kýrie eléison.\n℟. Kýrie eléison.\n℣. Christe eléison.\n℟. Christe eléison.\n℣. Kýrie eléison.\n℟. Kýrie eléison.\n℣. Pater de cǽlis, Deus. R. Miserére nobis.\n℣. Fili Redémptor mundi, Deus. R. Miserére nobis.\n℣. Spíritus Sancte, Deus. R. Miserére nobis.\n℣. Sancta Trínitas, unus Deus. R. Miserére nobis.\n℣. Sancta María. R. Ora pro nobis.\n℣. Sancta Dei Génetrix. R. Ora pro nobis.\n℣. Sancta Virgo vírginum. R. Ora pro nobis.\n℣. Sancte Míchaël. R. Ora pro nobis.\n℣. Sancte Gábriel. R. Ora pro nobis.\n℣. Sancte Ráphaël. R. Ora pro nobis.\n℣. Omnes sancti Angeli et Archángeli. R. Oráte pro nobis.\n℣. Omnes sancti beatórum Spirítuum órdines. R. Oráte pro nobis.","hr":"Gospodine smiluj se.\nGospodine smiluj se.\nKriste smiluj se.\nKriste smiluj se.\nGospodine smiluj se.\nGospodine smiluj se.\nOče nebeski, Bože, smiluj nam se.\nSine, Otkupitelju svijeta, Bože, smiluj nam se.\nDuše Sveti, Bože, smiluj nam se.\nSveto Trojstvo, jedan Bože, smiluj nam se.\nSveta Marijo, moli za nas!\nSveta Bogorodice, moli za nas!\nSveta Djevo djevica, moli za nas!\nSveti Mihovile, moli za nas!\nSveti Gabrijele, moli za nas!\nSveti Rafaele, moli za nas!\nSvi sveti anđeli i arkanđeli, molite za nas!\nSvi sveti redovi blaženih duhova, molite za nas.","src":"Kniewald 1942, str. 294"},{"la":"℣. Sancte Ioánnes Baptísta. R. Ora pro nobis.\n℣. Sancte Ioseph. R. Ora pro nobis.\n℣. Omnes sancte Patriárchæ et Prophétæ. R. Oráte pro nobis.","hr":"Sveti Ivane Krstitelju, moli za nas.\nSveti Josipe, moli za nas!\nSvi sveti patrijarsi i proroci, molite za nas!","src":"Kniewald 1942, str. 294"},{"la":"℣. Sancte Petre. R. Ora pro nobis.\n℣. Sancte Paule. R. Ora pro nobis.\n℣. Sancte Andréa. R. Ora pro nobis.\n℣. Sancte Ioánnes. R. Ora pro nobis.\n℣. Omnes sancti Apóstoli et Evangelístæ. R. Oráte pro nobis.\n℣. Omnes sancti Discípuli Dómini. R. Oráte pro nobis.","hr":"Sveti Petre, moli za nas!\nSveti Pavle, moli za nas!\nSveti Andrija, moli za nas!\nSveti Ivane, moli za nas!\nSvi sveti apostoli i evanđelisti, molite za nas.\nSvi sveti učenici Gospodnji, molite za nas.","src":"Kniewald 1942, str. 294"},{"la":"℣. Sancte Stéphane. R. Ora pro nobis.\n℣. Sancte Laurénti. R. Ora pro nobis.\n℣. Sancte Vincénti. R. Ora pro nobis.\n℣. Omnes sancti Mártyres. R. Oráte pro nobis.\n℣. Sancte Silvéster. R. Ora pro nobis.\n℣. Sancte Gregóri. R. Ora pro nobis.\n℣. Sancte Augustíne. R. Ora pro nobis.\n℣. Omnes sancti Pontífices et Confessóres. R. Oráte pro nobis.\n℣. Omnes sancti Doctóres. R. Oráte pro nobis.","hr":"Sveti Stjepane, moli za nas!\nSveti Lovro, moli za nas!\nSveti Vinko, moli za nas!\nSvi sveti mučenici, molite za nas!\nSveti Silvestre, moli za nas!\nSveti Grgure, moli za nas!\nSveti Augustine, moli za nas!\nSvi sveti biskupi i ispovjednici, molite za nas.\nSvi sveti naučitelji, molite za nas.","src":"Kniewald 1942, str. 294-295"},{"la":"℣. Sancte Antóni. R. Ora pro nobis.\n℣. Sancte Benedícte. R. Ora pro nobis.\n℣. Sancte Domínice. R. Ora pro nobis.\n℣. Sancte Francísce. R. Ora pro nobis.\n℣. Omnes sancti Sacerdótes et Levítæ. R. Oráte pro nobis.\n℣. Omnes sancti Mónachi et Eremítæ. R. Oráte pro nobis.","hr":"Sveti Antune, moli za nas!\nSveti Benedikte, moli za nas!\nSveti Dominiče, moli za nas!\nSveti Franjo, moli za nas!\nSvi sveti svećenici i leviti, molite za nas.\nSvi sveti redovnici i pustinjaci, molite za nas.","src":"Kniewald 1942, str. 295"},{"la":"℣. Sancta María Magdaléna. R. Ora pro nobis.\n℣. Sancta Agnes. R. Ora pro nobis.\n℣. Sancta Cæcília. R. Ora pro nobis.\n℣. Sancta Agatha. R. Ora pro nobis.\n℣. Sancta Anastásia. R. Ora pro nobis.\n℣. Omnes sanctæ Vírgines et Víduæ. R. Oráte pro nobis.\n℣. Omnes Sancti et Sanctæ Dei. R. Intercédite pro nobis.\n[Postea, si ecclesia habet fontem baptismalem, ritus prosequitur ut infra.]","hr":"Sveta Marijo Magdaleno, moli za nas!\nSveta Agnezo, moli za nas!\nSveta Cecilijo, moli za nas!\nSveta Agato, moli za nas!\nSveta Anastazijo, moli za nas!\nSve svete djevice i udovice, molite za nas!\nSvi sveti i svetice Božje, zagovarajte nas!","src":"Kniewald 1942, str. 295"}]},{"kind":"section","la":"De benedictione aquæ baptismalis","hr":"","rows":[{"la":"[Dum cantantur Litaniæ Sanctorum, vas aquæ baptismalis benedicendæ, et cetera omnia quæ ad benedictionem requiruntur, præparantur in medio chori, versus latus Epistolæ, in conspectu fidelium. Vas aquæ benedicendæ convenienter ornari decet.]","hr":" "},{"la":"[In benedicenda aqua baptismali celebrans, stans coram populo, ante se habeat vas aquæ baptismalis benedicendæ, a dextris cereum benedictum, a sinistris alium subdiaconum, vel clericum, seu ministrantem, stantem cum cruce. Celebrans, iunctis manibus, in tono feriali dicit:]\n℣. Dóminus vobíscum. ℟. Et cum spíritu tuo.\nOrémus.\nOmnípotens sempitérne Deus, adésto magnæ pietátis tuæ mystériis, adésto sacraméntis: et ad recreándos novos pópulos, quos tibi fons baptismátis párturit, spíritum adoptiónis emítte ; ut, quod nostræ humilitátis geréndum est ministério, virtútis tuæ impleátur efféctu. Per Dóminum nostrum Iesum Christum, Fílium tuum: Qui tecum vivit et regnat in unitáte Spíritus Sancti Deus:\n[Elevans vocem in modum præfationis, prosequitur iunctis manibus:]\nPer ómnia sǽcula sæculórum.\n℟. Amen.\n℣. Dóminus vobíscum.\n℟. Et cum spíritu tuo.\n℣. Sursum corda.\n℟. Habémus ad Dóminum.\n℣. Grátias agámus Dómino Deo nostro.\n℟. Dignum et iustum est.\nVere dignum et iustum est, æquum et salutare, nos tibi semper et ubique gratias agere, Domine, sancte Pater, omnipotens æterne Deus: qui invisibili potentia, sacramentorum tuorum mirabiliter operaris effectum: et licet nos tantis mysteriis exsequendis simus indigni: tu tamen gratiæ tuæ dona non deserens, etiam ad nostras preces aures tuæ pietatis inclinas. Deus, cuius Spiritus super aquas inter ipsa munda primordia ferebatur: ut iam tunc virtutem sanctificationis, aquarum natura conciperet. Deus, qui nocentis mundi crimina per aquas abluens, regenerationis speciem in ipsa diluvii effusione signasti: ut, unius eiusdemque elementi mysterio, et finis esset vitiis, et origo virtutibus. Respice, Domine, in faciem Ecclesiæ tuæ, et multiplica in ea regenerationes tuas, qui gratiæ tuæ affluentis impetu lætificas civitatem tuam: fontemque baptismatis aperis toto orbe terrarum gentibus innovandis: ut, tuæ maiestatis imperio, sumat Unigeniti tui gratiam de Spiritu Sancto.","hr":"Gospodin s vama. I s duhom tvojim.\nPomolimo se.\nSvemogući, vječni Bože, bliz budi tajnama velike svoje blagosti, bliz budi otajstvima i pošalji duh posinaštva da okrijepi nove narode, što Ti ih rađa krsni vrutak: neka se napune učinkom Tvoje kreposti, što ima da učini smjerna naša služba, po G. n.\nPo sve vijeke vijekova.\nAmen.\nGospodin s vama.\nI s duhom tvojim.\nGore srca.\nImamo kod Gospodina.\nHvale uzdajmo Gospodinu Bogu našemu.\nDostojno je i pravedno.\nU istinu je dostojno i pravedno, pravo i spasonosno, da Tebi uvijek i svagdje zahvaljujemo, Gospodine sveti, Oče svemogući, vječni Bože, koji nevidljivom moću divno djeluješ učinak Tvojih otajstva. I premda smo nedostojni da svršujemo tolike tajne, ipak priklanjaš uši svoje blagosti našim molitvama ne napuštajući darova svoje milosti. Bože, Tvoj je Duh lebdio nad vodama u prvome početku svijeta, da bi već tada priroda vode začela moć posvećenja; Bože, Ti si zlodjela opakoga svijeta oprao vodom i obilježio u razlitom potopu način preporođenja, da bude u otajstvu jednoga istoga počela i kraj opačinama i početak krepostima. Obazri se, Gospodine, na lice Crkve svoje i umnoži u njoj preporođenja svoja, koji bujicom obilne svoje milosti razveseljuješ grad svoj i otvaraš vrutak krsni svemu svijetu za obnovu narodima: da na zapovijed veličanstva Tvojega primi milost Jedinorođenoga Tvoga od Duha Svetoga.","src":"Kniewald 1942, str. 291-292"},{"la":"[Hic celebrans in modum crucis aquam dividit manu extensa, quam statim linteo extergit, dicens:]","hr":" "},{"la":"Qui hanc aquam, regenerándis homínibus præparátam, arcána sui núminis admixtióne fecúndet: ut, sanctificatióne concépta, ab immaculáto divíni fontis útero, in novam renáta creatúram, progénies cæléstis emérgat: et quos aut sexus in córpore, aut ætas discérnit in témpore, omnes in unam páriat grátia mater infántiam. Procul ergo hinc, iubénte te, Dómine, omnis spíritus immúndus abscédat: procul tota nequítia diabólicæ fráudis absístat. Nihil hoc loci hábeat contráriæ virtútis admíxtio: non insidiándo circúmvolet: non laténdo subrépat: non inficiéndo corrúmpat.","hr":"Neka On ovu vodu, pripravljenu za preporođenje ljudima, tajnom primjesom Božanstva svojega oplodi, da začevši posvećenje iz neoskvrnjene utrobe božanstvenoga vrela izroni nebeski naraštaj ponovno rođen za novo stvorenje; i da majka milost porodi u jedno djetinjstvo sve, koje razlučuje bilo spol u tijelu, bilo doba u vremenu. Daleko, dakle, otuda po zapovijedi Tvojoj, Gospodine, neka odstupi svaki nečisti duh, daleko neka stoji svaka zloća đavolskoga lukavstva. Nikakova mjesta da ne ima ovdje protivne sile primjesa, vrebajući da ne oblijeće, da iz potaje ne dopuzi, da ne pokvari zarazom.","src":"Kniewald 1942, str. 292"},{"la":"[Aquam manu tangit.]","hr":" "},{"la":"Sit hæc sancta et ínnocens creatúra, líbera ab omni impugnatóris incúrsu, et totíus nequítiæ purgáta discéssu. Sit fons vivus, aqua regénerans, unda puríficans: ut omnes hoc lavácro salutífero diluéndi, operánte in eis Spíritu Sancto, perféctæ purgatiónis indulgéntiam consequántur.","hr":"Neka ovo sveto i nedužno stvorenje bude prosto od svakog nasrtaja napadača i očišćeno odlaskom svake zloće. Da bude vrutak živi, voda koja preporađa, val što čisti: da svi, što budu oprani ovom spasonosnom kupelju, djelovanjem Duha svetoga u njima dostignu oproštenje savršenog očišćenja.","src":"Kniewald 1942, str. 292"},{"la":"[Facit crucem super aquam, dicens:]","hr":" "},{"la":"Unde benedíco te, creatúra aquæ, per Deum + vivum, per Deum + verum, per Deum + sanctum: per Deum, qui te, in princípio, verbo separávit ab árida: cuius Spíritus super te ferebátur.","hr":"Toga radi blagosiljam te, stvorenje vode, Bogom † živim, Bogom † istinim, Bogom † svetim, Bogom, koji te u početku riječju odijeli od kopna; kojega Duh nad tobom lebđaše;","src":"Kniewald 1942, str. 292"},{"la":"[Hic manu aquam dividit, et effundit eam versus quatuor mundi partes, dicens:]","hr":" "},{"la":"Qui te paradísi fonte manáre fecit, et in quátuor flumínibus totam terram rigáre præcépit. Qui te in desérto amáram, suavitáte índita, fecit esse potábilem, et sitiénti pópulo de petra prodúxit. Bene + dico te et per Iesum Christum Fílium eius únicum, Dóminum nostrum: qui te in Cana Galilææ signo admirábili, sua poténtia convértit in vinum. Qui pédibus super te ambulávit: et a Ioánne in Iordáne in te baptizátus est. Qui te una cum sánguine de látere suo prodúxit: et discípulis suis iussit, ut credéntes baptizaréntur in te, dicens: Ite, docéte omnes gentes, baptizántes eos in nómine Patris, et Fílii, et Spíritus Sancti.","hr":"koji učini, da tečeš iz rajskoga izvora i zapovjedi, da u četiri rijeke natapaš svu zemlju; koji te gorku u pustinji učini pitkom ulivši slatkoću i iz stijene izvede žednomu puku. Blago † siljam te i po Isusu Kristu, jedinomu Sinu njegovu, Gospodinu našemu, koji te u Kani galilejskoj divnim čudom, svojom moću, pretvori u vino; koji nogama po tebi hodi i od Ivana u Jordanu u tebi se krsti; koji te zajedno s krvlju iz boka svojega izvede i učenicima svojim zapovjedi, da krštavaju vjernike u tebi, govoreći: Idite, učite sve narode, krsteći ih u ime Oca i Sina i Duha Svetoga.","src":"Kniewald 1942, str. 292-293"},{"la":"[Mutat vocem, et prosequitur recto tono:]","hr":" "},{"la":"Hæc nobis præcépta servántibus tu, Deus omnípotens, clemens adésto: tu benígnus aspíra.","hr":"Nama, koji ove zapovijedi opslužujemo, Ti, Bože svemogući, milostiv priteci: Ti blagostiv zadahni Duha Tvojega;","src":"Kniewald 1942, str. 293"},{"la":"[Halat ter in aquam in modum crucis, dicens:]","hr":" "},{"la":"Tu has símplices aquas tuo ore benedícito: ut præter naturálem emundatiónem, quam lavándis possunt adhibére corpóribus, sint étiam purificándis méntibus efficáces.","hr":"Ti ove jednostavne vode svojim ustima blagoslovi, da osim naravnoga čišćenja, što se može upotrebiti za pranje tijela, budu uspješne i za očišćavanje duša.","src":"Kniewald 1942, str. 293"},{"la":"[Hic celebrans paululum demittit cereum in aquam: et resumens tonum præfationis, dicit:]","hr":" "},{"la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti.","hr":"Neka siđe u ovu puninu izvora krepost Duha Svetoga","src":"Kniewald 1942, str. 293"},{"la":"[Deinde extractum cereum de aqua, iterum profundius mergit, aliquanto altius repetens:]","hr":" "},{"la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti.","hr":"Neka siđe u ovu puninu izvora krepost Duha Svetoga","src":"Kniewald 1942, str. 293"},{"la":"[Postea cereum rursus de aqua extractum, tertio immergens usque ad fundum, altiori adhuc voce repetit:]","hr":" "},{"la":"Descéndat in hanc plenitúdinem fontis virtus Spíritus Sancti.","hr":"Neka siđe u ovu puninu izvora krepost Duha Svetoga","src":"Kniewald 1942, str. 293"},{"la":"[Descendat, ut supra. Et deinde sufflans ter in aquam, secundum hanc figuram &Psi;, prosequitur:]","hr":" "},{"la":"Totámque huius aquæ substántiam, regenerándi fecúndet efféctu.\nTotámque huius aquæ substántiam, regenerándi fecúndet efféctu.\nTotámque huius aquæ substántiam, regenerándi fecúndet efféctu.","hr":"i da svekoliku bit ove voda oplodi učinkom preporoda.","src":"Kniewald 1942, str. 293"},{"la":"[Hic tollitur cereus de aqua, et prosequitur:]","hr":" "},{"la":"Hic ómnium peccatórum máculæ deleántur: hic natúra ad imáginem tuam cóndita, et ad honórem sui reformáta princípii, cunctis vetustátis squalóribus emundétur: ut omnis homo, sacraméntum hoc regeneratiónis ingréssus, in veræ innocéntiæ novam infántium renascátur.","hr":"Ovdje se zastrle sve ljage grijeha, ovdje se priroda na sliku Tvoju stvorena i obnovljena na čast svoga začetka očistila od svih starinskih nečistoća: da se svaki čovjek, što uđe u ovo otajstvo preporoda, nanovo rodi kao dijete prave nevinosti:","src":"Kniewald 1942, str. 293"},{"la":"[Sequentia dicit legendo:]","hr":" "},{"la":"Per Dóminum nostrum Iesum Christum Fílium tuum: qui ventúrus est iudicáre vivos et mórtuos, et sǽculum per ignem. R. Amen.","hr":"po Gospodinu našem Isusu Kristu, koji ima doći suditi žive i mrtve i svijet ognjem.","src":"Kniewald 1942, str. 293"},{"la":"[Deinde aliquis clericus, vel ministrans, accipit in vase aliquo de eadem aqua, ad aspergendum populum post renovationem promissionum Baptismatis, ut infra, dicetur, et ad aspergendum in domibus et aliis locis.]","hr":" "},{"la":"[His peractis, celebrans, qui benedicit aquam, infundit de oleo catechumenorum in eam in modum crucis, intellegibili voce dicens:]\nSanctificétur + et fecundétur fons iste Oleo salútis renascéntibus ex eo, in vitam ætérnam.\n℟. Amen.","hr":"Da se posveti i oplodi ovo vrelo uljem spasenja za one, što će se iz njega nanovo roditi u život vječni.\nAmen.","src":"Kniewald 1942, str. 293"},{"la":"[Deinde infundit de chrismate, modo quo supra, dicens:]\nInfúsio Chrísmatis Dómini nostri Iesu Christi, et Spíritus Sancti Parácliti, fiat in nómine sanctæ Trinitátis.\n℟. Amen.","hr":"Naljev krizme Gospodina našega Isusa Krista i Duha Svetoga Utješitelja neka bude u ime svetoga Trojstva.\nAmen.","src":"Kniewald 1942, str. 293"},{"la":"[Postea accipit ambas ampullas dicti olei sancti, et chrismatis, et de utroque simul in modum crucis infundendo, dicit:]\nCommíxtio Chrísmatis sanctificatiónis, et Olei unctiónis, et aquæ baptísmatis, páriter fiat in nómine Pa + tris, et Fí + lii, et Spíritus + Sancti.\n℟. Amen.","hr":"Pomiješanje krizme posvećenja i ulja pomazanja i vode krštenja, jednako neka budu u ime Oca i Sina i Duha Svetoga.\nAmen.","src":"Kniewald 1942, str. 293-294"},{"la":"[Tunc miscet ipsum oleum cum aqua. Si aderunt baptizandi, eos baptizet more consueto. Sed, præsertim si plures sint, permittitur cæremonias Ritualis romani, quæ ipsam Baptismi collationem præcedunt, id est, in Baptismate infantium usque ad verba Credis in Deum (Rituale romanum, tit. II, cap. II, n. 17), et in Baptismate adultorum usque ad verba Quis vocaris? (Rituale romanum, tit. II, cap. IV, n. 37), eodem mane, tempore opportuno, præmittere.]","hr":" "},{"la":"[Benedictione peracta, aqua baptismalis defertur processionaliter ad fontem, hoc modo: præcedit thuriferarius, sequitur alius subdiaconus, vel clericus, cum cruce, et clerus; deinde diaconus cum vase aquæ baptismalis, nisi conveniat ipsum ab acolythis portari, et celebrans; cereus vero paschalis remanet in suo loco; et interim cantatur sequens]","hr":" "},{"la":"[Canticum]\nPs 41:2-4\nSicut cervus desíderat ad fontes aquárum: ita desíderat ánima mea ad te, Deus.\n℣. Sitívit ánima mea ad Deum vivum, quando véniam, et apparébo ante fáciem Dei?\n℣. Fuérunt mihi lácrymæ meæ panes die ac nocte, dum dícitur mihi per síngulos dies: Ubi est Deus tuus?\n[Aqua baptismali in fontem immissa, celebrans, manibus iunctis et in tono feriali, dicit:]\n℣. Dóminus vobíscum. ℟. Et cum spíritu tuo.\nOrémus.\nOmnípotens sempitérne Deus, réspice propítius ad devotiónem pópuli renascéntis, qui sicut cervus, aquárum tuárum éxpetit fontem: et concéde propítius; ut fídei ipsíus sitis, baptísmatis mystério, ánimam corpúsque sanctíficet. Per Dóminum nostrum Iesum Christum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum.\n℟. Amen.\n[Et incensat fontem.]","hr":"Ps. 41, 2, 14\nKao što čezne jelen za izvor-vodom, tako čezne duša moja za Tobom, Bože.\nŽeđa duša moja Boga jakoga, živoga, kad ću doći i pokazati se pred licem Božjim?\nSuze su mi kruh danju i noću, kad mi govore svaki dan: Gdje je Bog tvoj?\nGospodin s vama. I s duhom tvojim.\nPomolimo se.\nSvemogući, vječni Bože, obazri se milostivo na pobožni puk svoj, što se preporađa i kao jelen traži vrutak Tvojih voda, pa daj milostivo, da žeđ vjere krsnim otajstvom posveti dušu i tijelo, po G. n.","src":"Kniewald 1942, str. 290-291"},{"la":"[Tunc redeunt omnes in silentio in chorum, et datur initium renovationi promissionum Baptismatis.]","hr":" "},{"la":"[(Benedictione peracta, aqua baptismalis defertur processionaliter ad fontem, hoc modo: præcedit thuriferarius, sequuntur crucifer et ministrantes; deinde unus vel plures ministrantium, qui vas aquæ baptismalis gestant, et sacerdos; cereus vero paschalis remanet in suo loco. Cetera fiunt ut supra.)]","hr":" "},{"la":"[Sicubi vero baptisterium exstat ab ecclesia separatum, et præferatur benedictionem aquæ baptismalis in ipso baptisterio fieri, post invocationem Sancta Trínitas, unus Deus, miserere nobis, descenditur ad fontem hoc modo: præcedit clericus cum cereo benedicto, sequitur alius subdiaconus cum cruce, vel crucifer, medius inter acolythos cum candelabris accensis, deinde clerus per ordinem, demum celebrans cum ministris sacris. Cantores vero et populus remanent in locis suis, et prosequuntur cantum Litaniarum, repetitis, si opus est, invocationibus inde a Sancta María, ora pro nobis. Benedictio aquæ baptismalis fit ut supra, his tantum mutatis: dum pergitur ad fontem, cantatur canticum Sicut cervus, et celebrans, antequam intret ad benedictionem fontis, dicit orationem Omnípotens sempitérne Deus, respice propitius; postea procedit ad benedictionem fontis. Benedictione peracta, omnes redeunt in silentio in ecclesiam, et datur initium renovationi promissionum Baptismatis.]","hr":" "}]},{"kind":"section","la":"De renovatione promissionum baptismatis","hr":"","rows":[{"la":"[Completa benedictione aquæ baptismalis, eiusque translatione ad fontem, vel, ubi benedictio locum non habuerit, post absolutam primam partem Litaniarum, proceditur ad renovationem promissionum Baptismatis, qua perdurante convenit, ut clerus et populus candelas accensas gestent.]","hr":" "},{"la":"[Celebrans, depositis paramentis violaceis, assumit stolam et pluviale albi coloris; deinde, imposito thure, et facta incensatione cerei, stans iuxta illum, facie versus ad populum, vel ex ambone seu pulpito, incipit, ut sequitur:]","hr":" "},{"la":"Hac sacratíssima nocte, fratres caríssimi, sancta Mater Ecclésia, recólens Dómini nostri Iesu Christi mortem ei sepultúram, eum redamándo vígilat; et, célebrans eiúsdem gloriósam resurrectiónem, lætabúnda gáudet.","hr":""},{"la":"Quóniam vero, ut docet Apóstolus, consepúlti sumus cum Christo per baptísmum in mortem, quómodo Christus resurréxit a mórtuis, ita et nos in novitáte vitæ opórtet ambuláre; sciéntes, véterem hóminem nostrum simul cum Christo crucifíxum esse, ut ultra non serviámus peccáto. Existimémus ergo nos mórtuos quidem esse peccáto, vivéntis áutem Deo in Christo Iesu Dómino nostro.","hr":""},{"la":"Quaprópter, fratres caríssimi, quadragesimáli exercitatióne absolúta, sancti baptísmatis promissiónis renovémus, quibus olim sátanæ et opéribus eius, sicut et mundo, qui inimícus est Dei, abrenuntiávimus, et Deo in sancta Ecclésia cathólica fidéliter servíre promísimus.","hr":""},{"la":"Itaque:\nAbrenuntiátis Sátanæ?\nO. Abrenuntiámus.\nEt ómnibus opéribus eius?\nO. Abrenuntiámus.\nEt ómnibus pompis eius?\nO. Abrenuntiámus.\nCréditis in Deum, Patrem omnipoténtem, Creatórem cœli et terræ?\nO. Crédimus.\nCréditis in Iesum Christum, Fílium eius únicum, Dóminum nostrum, natum et passum?\nO. Crédimus.\nCréditis et in Spíritum Sanctum, sanctam Ecclésiam cathólicam, Sanctórum communiónem, remissiónem peccatórem, carnis resurrectiónem, et vitam ætérnam?\nO. Crédimus.\nNunc áutem una simul Deum precémur, sicut Dóminus noster Iesus Christus oráre nos dócuit:\nO. Pater noster, qui es in cœlis, sanctificétur nomen tuum. Advéniat regnum tuum. Fiat volúntas tua, sicut in cœlo et in terra. Panem nostrum quotidiánum da nobis hódie, et dimítte nobis débita nostra, sicut et nos dimíttimus debitóribus nostris. Et ne nos indúcas in tentatiónem, sed líbera nos a malo.\nEt Deus omnípotens, Pater Dómini nostri Iesu Christi, qui nos regenerávit ex aqua et Spíritu Sancto, quique nobis dedit remissiónem peccatórum, ipse nos custódiat grátia sua in eódem Christo Iesu Dómino nostro in vitam ætérnam.\nO. Amen.","hr":""},{"la":"[Et aspergit populum aqua benedicta, extracta, ut supra dictum est, in benedictione aquæ baptismalis; vel, ubi benedictio aquæ baptismalis locum non habet, aqua benedicta «ordinaria».]","hr":" "},{"la":"[Hæc allocutio et renovatio promissionum Baptismatis fieri potest, ubique locorum, lingua vernacula; versione tamen ab Ordinario loci approbata.]","hr":" "}]},{"kind":"section","la":"De altera parte Litaniarum","hr":"","rows":[{"la":"[Renovatione promissionum Baptismatis peracta, cantores, seu ipse sacerdos, incipiunt alteram partem Litaniarum, inde ab invocatione Propitius esto, usque ad finem, omnibus genuflexis et respondentibus. Si in hac sacra Vigilia paschali Ordines conferantur, consueta ordinandorum prostrati et benedictio peragitur, dum hæc altera pars Litaniarum decantatur.]","hr":" "},{"la":"[Celebrans vero et ministri, accedentes ad sacristiam, induuntur paramentis albi coloris pro Missa solemniter celebranda.]","hr":" "},{"la":"[(Sacerdos vero et ministrantes accedunt ad sacristiam, ubi sacerdos induitur paramentis albi coloris, ministrantes vero sumunt vestes festivas, pro Missa cantata. Vel si, cantoribus deficientibus, ipse sacerdos Litanias Sanctorum decantare debeat, his ab solutis, ad sacristiam accedat, cum ministrantibus, ad paramenta sumenda pro Missa cant at a, ut supra dictum est.)]","hr":" "},{"la":"[Interim cereus paschalis reponitur in candelabro suo, in latere Evangelii, et altare paratur pro Missa solemni, luminaribus accensis et floribus.]","hr":" "},{"la":"℣. Propítius esto. R. Parce nobis, Dómine.\n℣. Propítius esto. R. Exaudi nos, Dómine.\n℣. Ab omni malo. R. Líbera nos, Dómine.\n℣. Ab omni peccáto. R. Líbera nos, Dómine.\n℣. A morte perpétua. R. Líbera nos, Dómine.\n℣. Per mystérium sanctæ Incarnatiónis tuæ. R. Líbera nos, Dómine.\n℣. Per advéntum tuum. R. Líbera nos, Dómine.\n℣. Per nativitátem tuum. R. Líbera nos, Dómine.\n℣. Per baptísmum et sanctum ieiúnium tuum. R. Líbera nos, Dómine.\n℣. Per crucem et passiónem tuam. R. Líbera nos, Dómine.\n℣. Per mortem et sepultúram tuam. R. Líbera nos, Dómine.\n℣. Per sanctam resurrectiónem tuam. R. Líbera nos, Dómine.\n℣. Per admirábilem ascensiónem tuam. R. Líbera nos, Dómine.\n℣. Per advéntum Spíritus Sancti Parácliti. R. Líbera nos, Dómine.\n℣. In die iudícii. R. Líbera nos, Dómine.","hr":"Milostiv budi, oprosti nam Gospodine!\nMilostiv budi, usliši nas Gospodine!\nOd svakoga zla, oslobodi nas, Gospodine.\nOd svakoga grijeha, oslobodi nas, Gospodine.\nOd smrti vječne, oslobodi nas, Gospodine.\nPo otajstvu svetoga utjelovljenja svoga, oslobodi nas, Gospodine.\nPo došašću svojem, oslobodi nas, Gospodine.\nPo rođenju svojem, oslobodi nas, Gospodine.\nPo krštenju i svetom postu svojem, oslobodi nas, Gospodine.\nPo križu i muci svojoj, oslobodi nas, Gospodine.\nPo smrti i ukopu svojem, oslobodi nas, Gospodine.\nPo svetom uskrsnuću svojem, oslobodi nas, Gospodine.\nPo čudesnom uzašašću svojem, oslobodi nas, Gospodine.\nPo dolasku Duha Svetoga Utješitelja, oslobodi nas, Gospodine.\nU dan sudnji, oslobodi nas, Gospodine.","src":"Kniewald 1942, str. 295 i 915"},{"la":"℣. Peccatóres. R. Te rogámus, audi nos.\n℣. Ut nobis parcas. R. Te rogámus, audi nos.\n℣. Ut Ecclésiam tuam sanctam régere et conserváre dignéris. R. Te rogámus, audi nos.\n℣. Ut domnum apostólicum et omnes ecclesiásticos órdines in sancta religióne conserváre dignéris. R. Te rogámus, audi nos.\n℣. Ut inimícos sanctæ Ecclésiæ humiliáre dignéris. R. Te rogámus, audi nos.\n℣. Ut régibus et princípibus christiánis, pacem et veram concórdiam donáre dignéris. R. Te rogámus, audi nos.\n℣. Ut nosmetípsos in tuo sancto servítio confortáre et conserváre dignéris. R. Te rogámus, audi nos.\n℣. Ut ómnibus benefactóribus nostris sempitérna bona retríbuas. R. Te rogámus, audi nos\n℣. Ut fructus terræ dare et conserváre dignéris. R. Te rogámus, audi nos.\n℣. Ut ómnibus fidélibus defúnctis réquiem ætérnam donáre dignéris. R. Te rogámus, audi nos.\n℣. Ut nos exaudíre dignéris. R. Te rogámus, audi nos.","hr":"Grješnici: — molimo te, usliši nas!\nDa nam oprostiš, — molimo te, usliši nas!\nDa se dostojiš svetu svoju Crkvu ravnati i uzdržati, molimo te, usliši nas!\nDa se dostojiš poglavicu apostolskoga i sve crkvene redove u svetoj vjeri uzdržati, molimo te, usliši nas!\nDa se dostojiš neprijatelje svete Crkve poniziti, molimo te, usliši nas!\nDa se dostojiš kraljevima i vladarima kršćanskim mir i pravu slogu darovati, molimo te, usliši naš!\nDa se dostojiš nas same u svetoj svojoj službi potkrijepiti i uzdržati, molimo te, usliši nas!\nDa sve dobrotvore naše vječnim dobrima naplatiš, molimo te, usliši nas!\nDa se dostojiš plodove zemlji dati i uzdržati, molimo te, usliši nas!\nDa se dostojiš svim vjernim mrtvima pokoj vječni darovati, molimo te, usliši nas!\nDa se dostojiš uslišiti nas, molimo te, usliši nas!","src":"Kniewald 1942, str. 296 i 915"},{"la":"℣. Agnus Dei, qui tollis peccáta mundi. R. Parce nobis, Dómine.\n℣. Agnus Dei, qui tollis peccáta mundi. R. Exaudi nos, Dómine.\n℣. Agnus Dei, qui tollis peccáta mundi. R. Miserére nobis.\n℣. Christe, audi nos.\n℟. Christe, exáudi nos.","hr":"Jaganjče Božji, koji uzimaš grijehe svijeta, oprosti nam, Gospodine!\nJaganjče Božji, koji uzimaš grijehe svijeta, usliši nas, Gospodine!\nJaganjče Božji, koji uzimaš grijehe svijeta, smiluj nam se!\nKriste, čuj nas.\nKriste, usliši nas.","src":"Kniewald 1942, str. 296 i 916"}]},{"kind":"section","la":"De Missa solemni Vigiliæ paschalis","hr":"","rows":[{"la":"[Celebratio solius Missæ Vigiliæ paschalis sine cæremoniis præcedentibus interdicitur.]","hr":" "},{"la":"[Sacra Communio fidelibus dari potest tantummodo inter Missarum solemnia, vel continuo ac statim ab iis expletis; exceptis iis, qui in periculo mortis sunt constituti.]","hr":" "},{"la":"[In fine Litaniarum, cantores solemniter incipiunt Kyrie, eléison, ut in Missa moris est. Interim celebrans cum ministris, in paramentis albis, seu cum ministrantibus, accedit ad altare, et, facta ei debita reverentia, omissis psalmo Iudica me, Deus, et confessione, statim ascendens, osculatur illud in medio, et incensat more solito.]","hr":" "},{"la":"[Celebrans benedicit, dicens:]\nAb illo bene + dicáris, in cujus honore cremáberis. Amen.","hr":""}]},{"kind":"section","la":"Kyrie","hr":"","rows":[{"la":"Kýrie, eléison.\nKýrie, eléison.\nKýrie, eléison.\nChriste, eléison.\nChriste, eléison.\nChriste, eléison.\nKýrie, eléison.\nKýrie, eléison.\nKýrie, eléison.","hr":"Gospodine smiluj se!\nGospodine smiluj se!\nGospodine smiluj se!\nKriste smiluj se!\nKriste smiluj se!\nKriste smiluj se!\nGospodine smiluj se!\nGospodine smiluj se!\nGospodine smiluj se!","src":"Kniewald 1942, str. 12"}]},{"kind":"section","la":"Glória in excélsis","hr":"Slava","rows":[{"la":"[Finitis a choro Kyrie, eléison, celebrans incipit solemniter Glória in excelsis, et pulsantur campanæ ac discooperiuntur imagines.]","hr":" "},{"text":"Na ovoj misi govori se Gloria"}]},{"kind":"section","la":"Orátio","hr":"Molitva","rows":[{"la":"Orémus.\nDeus, qui hanc sacratíssimam noctem glória domínicæ Resurrectiónis illústras: consérva in nova famíliæ tuæ progénie adoptiónis spíritum, quem dedísti; ut, córpore et mente renováti, puram tibi exhíbeant servitútem.\n<i>Per eúndem Dóminum nostrum Jesum Christum Fílium tuum, qui tecum vivit et regnat in unitáte Spíritus Sancti, Deus, per ómnia sǽcula sæculórum</i>.","hr":"Pomolimo se.\nBože, koji ovu presvetu noć prosvjetljuješ slavom uskrsnuća Gospodnjega, uzdrži u novom podmlatku obitelji svoje duh posinaštva, što ga dade, da obnovljeni tijelom i duhom prikazuju Tebi službu čistu, po istom G. n.","key":"vigil:oratio","src":"Kniewald 1942, str. 297"}]},{"kind":"section","la":"Epístola","hr":"Poslanica","rows":[{"la":"Léctio Epístolæ beáti Pauli Apóstoli ad Colossénses.\nCol 3:1-4\nFratres: Si consurrexístis cum Christo, quæ sursum sunt quǽrite, ubi Christus est in déxtera Dei sedens: quæ sursum sunt sápite, non quæ super terram. Mórtui enim estis, et vita vestra est abscóndita cum Christo in Deo. Cum Christus apparúerit, vita vestra: tunc et vos apparébitis cum ipso in glória.","hr":"Čitanje poslanice bl. Pavla apostola Kološanima (3, 1-4).\nBraćo! Ako ste uskrsnuli s Kristom, tražite ono, što je gore, gdje Krist sjedi s desne strane Božje; mislite na nebeske stvari, a ne na zemaljske. Jer ste umrli, vaš je život s Kristom sakriven u Bogu. A kada se pojavi Krist, vaš život, tada ćete se i vi pojaviti s njim u slavi.","key":"vigil:epistola","src":"Kniewald 1942, str. 297"}]},{"kind":"section","la":"Allelúia","hr":"Aleluja","rows":[{"la":"[Finita Epistola, celebrans incipit:]\n[Et totum decantat ter, elevando vocem gradatim: et omnes post quamlibet vicem, in eodem tono, repetunt illud idem:]","hr":" "},{"la":"Allelúia. Allelúia. Allelúia.\nPs. 117, 1\n℣. Confitémini Dómino, quóniam bonus: quóniam in sǽculum misericórdia eius.","hr":"Aleluja. Aleluja. Aleluja.\n(Ps. 117, 1). Hvalite Gospodina, jer je dobar, jer je do vijeka milosrđe njegovo.","key":"vigil:alleluia","src":"Kniewald 1942, str. 297"},{"la":"Ps. 116\n℣. Laudáte Dóminum, omnes gentes: et collaudáte eum, omnes pópuli.\n℣. Quóniam confirmáta est super nos misericórdia eius: et véritas Dómini manet in ætérnum.","hr":"(Ps. 116, 2). Hvalite Gospodina sva plemena, hvalite ga svi narodi: Jer je silno nad nama milosrđe njegovo i istina Gospodnja ostaje dovijeka.","key":"vigil:tractus","src":"Kniewald 1942, str. 297"}]},{"kind":"section","la":"Evangélium","hr":"Evanđelje","rows":[{"la":"[Ad Evangelium non portantur luminaria, sed tantum incensum: petitur benedictio, et alia fiunt de more.]","hr":" "},{"la":"Sequéntia ✠ sancti Evangélii secúndum Matthǽum.\nMatt 28:1-7\nVéspere autem sábbati, quæ lucéscit in prima sábbati, venit María Magdaléne, et áltera María vidére sepúlcrum. Et ecce terræmótus factus est magnus. Angelus enim Dómini descéndit de cælo: et accédens revólvit lápidem, et sedébat super eum: erat autem aspéctus eius sicut fulgur: et vestiméntum eius sicut nix. Præ timóre autem eius extérriti sunt custódes, et facti sunt velut mórtui. Respóndens autem Angelus, dixit muliéribus: «Nolíte timére vos: scio enim, quod Iesum, qui crucifíxus est, quǽritis: non est hic: surréxit enim, sicut dixit. Veníte, et vidéte locum, ubi pósitus erat Dóminus. Et cito eúntes dícite discípulis eius, quia surréxit et ecce præcédit vos in Galilǽam: ibi eum vidébitis. Ecce prædíxi vobis».","hr":"† Slijedi sveto evanđelje po Mateju (28, 1-7).\nPoslije subote, kad je svitao prvi dan po suboti, dođe Marija Magdalena i druga Marija, da pogledaju grob. I gle, silno se potrese zemlja, jer anđeo Gospodnji siđe s neba, pristupi, odvali kamen i sjedio je na njemu. Lice je njegovo bilo kao munja, a njegovo odijelo kao snijeg. Stražari od straha pred njim uzdrhtaše i bili su kao mrtvi. Tada anđeo progovori ženama: Nemojte se bojati! Znam, da tražite raspetoga Isusa. Nema ga ovdje, jer je uskrsnuo, kako je rekao. Dođite i vidite mjesto, gdje je bio Gospodin položen. Požurite se i javite učenicima, da je uskrsnuo. I eto ide pred vama u Galileju i tamo ćete ga vidjeti. Evo, rekao sam vam unaprijed.","key":"vigil:evangelium","src":"Kniewald 1942, str. 297-298"},{"text":"Na ovoj misi NE govori se Nicejsko-carigradsko vjerovanje"},{"la":"[Non dicitur antiphona ad Offertorium. Ad Lavabo dicitur Glória Patri.]","hr":" "}]},{"kind":"section","la":"Secréta","hr":"Prikazna molitva","rows":[{"la":"Súscipe, quǽsumus, Dómine, preces pópuli tui, cum oblatiónibus hostiárum: ut paschálibus initiáta mystériis, ad æternitátis nobis medélam, te operánte, profíciant.\n<i>Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte Spíritus Sancti Deus, per ómnia sǽcula sæculórum</i>.","hr":"Primi, molimo, Gospodine, molitve puka svoga s prinosima žrtava, da nam vazmenim tajnama i Tvojim djelovanjem budu korisne za vječnu okrepu, po G. n.","key":"vigil:secreta","src":"Kniewald 1942, str. 298"}]},{"kind":"section","la":"Praefátio paschális","hr":"Predslovlje uskrsno","rows":[{"la":"Vere dignum et justum est, æquum et salutáre: Te quidem, Dómine, omni témpore, sed in hac potíssimum nocte gloriósius prædicáre, cum Pascha nostrum immolátus est Christus. Ipse enim verus est Agnus, qui ábstulit peccáta mundi. Qui mortem nostram moriéndo destrúxit et vitam resurgéndo reparávit. Et ídeo cum Angelis et Archángelis, cum Thronis et Dominatiónibus cumque omni milítia cœléstis exércitus hymnum glóriæ tuæ cánimus, sine fine dicéntes:","hr":"Uistinu je dostojno i pravedno, pravo i spasonosno da tebe, Gospodine, u svako doba, a osobito <i>ove noći</i> svečanije slavimo, kad je Krist žrtvovan, naše vazmeno Janje. On je naime pravo janje koje oduze grijehe svijeta. Svojom smrću on je uništio našu smrt i svojim uskrsnućem obnovio naš život. – I stoga s anđelima i arkanđelima, s prijestoljima i gospodstvima i sa svom nebeskom vojskom pjesmu tvoje slave pjevamo bez prestanka:","key":"vigil:prefatio","src":"tradicionalnamisa.com (uskrsno predslovlje); promjenjive riječi »osobito ove noći« prema Kniewald 1942, str. 298"},{"la":"[Agnus Dei non dicitur: et, omissa oratione Dómine Iesu Christe, qui dixísti, dicuntur ceteræ orationes consuetæ:]","hr":" "}]},{"kind":"section","la":"Pro Láudibus","hr":"Jutarnja","rows":[{"la":"[Post sumptionem Sacramenti, distributio Communionis, purificatio et ablutio fiunt more solito; deinde pro LAUDIBUS dominicæ Resurrectionis in choro cantatur antiphona:]","hr":" "},{"la":"Ant. Allelúia, allelúia, allelúia.\nPsalmus 150\nLaudáte Dóminum in sanctis eius * laudáte eum in firmaménto virtútis eius.\nLaudáte eum in virtútibus eius, * laudáte eum secúndum multitúdinem magnitúdinis eius.\nLaudáte eum in sono tubæ, * laudáte eum in psaltério, et cíthara.\nLaudáte eum in týmpano, et choro: * laudáte eum in chordis et órgano.\nLaudáte eum in cýmbalis benesonántibus: laudáte eum in cýmbalis iubilatiónis: * omnes spíritus laudet Dóminum.\nGlória Patri, et Fílio, et Spirítui Sancto. Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.\nAnt. Allelúia, allelúia, allelúia.","hr":"","key":"vigil:laudes-ps150"},{"la":"[Capitulum, hymnus et versus non dicuntur, sed statim celebrans in cantu incipit antiphonam ad Benedíctus.]","hr":" "},{"la":"Ant. Et valde mane una sabbatórum, véniunt ad monuméntum, orto iam sole, allelúia.","hr":"I prvoga dana po suboti, vrlo rano, kad je sunce izlazilo, dođu na grob, <i>aleluja</i>.","key":"vigil:laudes-antiphona","src":"tradicionalnamisa.com, evanđelje Uskrsa (Mk 16, 2), skraćeno na opseg antifone; dodano Aleluja"},{"la":"[Deinde cantatur Benedíctus, cum Glória Patri in fine, et fit incensatio, ut alias in Laudibus.]","hr":" "},{"la":"Luc 1:68-79\nBenedíctus ✠ Dóminus, Deus Israël: * quia visitávit, et fecit redemptiónem plebis suæ:\nEt eréxit cornu salútis nobis: * in domo David, púeri sui.\nSicut locútus est per os sanctórum, * qui a sǽculo sunt, prophetárum ejus:\nSalútem ex inimícis nostris, * et de manu ómnium, qui odérunt nos.\nAd faciéndam misericórdiam cum pátribus nostris: * et memorári testaménti sui sancti.\nJusjurándum, quod jurávit ad Ábraham patrem nostrum, * datúrum se nobis:\nUt sine timóre, de manu inimicórum nostrórum liberáti, * serviámus illi.\nIn sanctitáte, et justítia coram ipso, * ómnibus diébus nostris.\nEt tu, puer, Prophéta Altíssimi vocáberis: * præíbis enim ante fáciem Dómini, paráre vias ejus:\nAd dandam sciéntiam salútis plebi ejus: * in remissiónem peccatórum eórum:\nPer víscera misericórdiæ Dei nostri: * in quibus visitávit nos, óriens ex alto:\nIllumináre his, qui in ténebris, et in umbra mortis sedent: * ad dirigéndos pedes nostros in viam pacis.\nGlória Patri, et Fílio, et Spirítui Sancto. Sicut erat in princípio, et nunc, et semper, et in sǽcula sæculórum. Amen.","hr":"","key":"vigil:laudes-benedictus"},{"la":"Ant. Et valde mane una sabbatórum, véniunt ad monuméntum, orto iam sole, allelúia.","hr":"I prvoga dana po suboti, vrlo rano, kad je sunce izlazilo, dođu na grob, <i>aleluja</i>.","key":"vigil:laudes-antiphona","src":"tradicionalnamisa.com, evanđelje Uskrsa (Mk 16, 2), skraćeno na opseg antifone; dodano Aleluja"}]},{"kind":"section","la":"Postcommúnio","hr":"Popričesna","rows":[{"la":"Orémus.\nSpíritum nobis, Dómine, tuæ caritátis infúnde: ut, quos sacraméntis paschálibus satiásti, tua fácias pietáte concórdes.\n<i>Per Dóminum nostrum Jesum Christum, Fílium tuum: qui tecum vivit et regnat in unitáte ejúsdem Spíritus Sancti Deus, per ómnia sǽcula sæculórum</i>.","hr":"Pomolimo se.\nUlij nam, Gospodine, duh ljubavi svoje, da svojom milostivošću učiniš složnima, koje si nahranio vazmenim tajnama, po G. n.","key":"vigil:postcommunio","src":"Kniewald 1942, str. 298"}]},{"kind":"section","la":"Conclúsio","hr":"Otpust","rows":[{"la":"℣. Ite, Missa est, allelúia, allelúia.\n℟. Deo grátias, allelúia, allelúia.","hr":"℣. Idite misa je! Aleluja, aleluja.\n℟. Bogu hvala, aleluja, aleluja.","key":"vigil:ite","src":"Kniewald 1942, str. 30 (Red mise); Aleluja udvostručen prema latinskom"},{"la":"[Omisso ultimo Evangelio, omnes revertuntur in sacristiam.]","hr":" "}]}]});
